import{Tt as e,at as t,rt as n,t as r}from"./chunks/framework.j55wycBY.js";var i=JSON.parse(`{"title":"Stripe webhook","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/homelab/stripe-webhook.md","filePath":"deploy/homelab/stripe-webhook.md"}`),a={name:`deploy/homelab/stripe-webhook.md`};function o(r,i,a,o,s,c){return e(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795511872000`},[...i[0]||=[t(`<h1 id="stripe-webhook" tabindex="-1">Stripe webhook <a class="header-anchor" href="#stripe-webhook" aria-label="Permalink to “Stripe webhook”">​</a></h1><p>For the homelab Stripe <strong>sandbox</strong>, create a webhook endpoint with:</p><ul><li><strong>Scope:</strong> Your account. This is a routing scope, not a request to use Accounts v2 events; Notopia does not use Stripe Connect.</li><li><strong>Payload:</strong> Snapshot.</li><li><strong>API version:</strong> <code>2026-10-28.endive</code>, matching <code>stripe-go/v87</code>. If only <code>2026-11-18.endive</code> is available, test it; it is in the same Endive release family.</li><li><strong>URL:</strong> <code>https://notopia-api.&lt;PUBLIC_DOMAIN&gt;/billing/webhooks/stripe</code>.</li></ul><p>Select these events:</p><ul><li><code>checkout.session.completed</code></li><li><code>customer.subscription.created</code>, <code>customer.subscription.updated</code>, <code>customer.subscription.deleted</code></li><li><code>invoice.paid</code>, <code>invoice.payment_failed</code></li><li><code>refund.created</code>, <code>refund.updated</code>, <code>refund.failed</code></li></ul><p>The authoritative event list and handling are in <a href="https://github.com/notopia-uit/notopia/blob/main/internal/billing/controller/http/webhook.go" target="_blank" rel="noreferrer"><code>internal/billing/controller/http/webhook.go</code></a>. Check its event switch when updating the destination.</p><p>Store the destination&#39;s <code>whsec_...</code> signing secret as <code>NOTOPIA_BILLING_STRIPE_WEBHOOK_SECRET</code> and the sandbox API key as <code>NOTOPIA_BILLING_STRIPE_SECRET_KEY</code>, following the <a href="https://github.com/notopia-uit/notopia/blob/main/deploy/k8s/clusters/homelab/README.md" target="_blank" rel="noreferrer">homelab provisioning instructions</a>.</p>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};